<?php

namespace App\Support;

/**
 * Resolves the WebP variants generated by scripts/optimize-images.mjs
 * (img/foo.png -> img/foo-640.webp, img/foo-1280.webp, img/foo-1920.webp).
 */
class ResponsiveImage
{
    public const WIDTHS = [640, 1280, 1920];

    /** @var array<string, array<int, string>> */
    private static array $cache = [];

    /**
     * Existing WebP variants of a public image, keyed by width, smallest first.
     *
     * @return array<int, string> width => public URL
     */
    public static function variants(string $path): array
    {
        return self::$cache[$path] ??= self::resolve($path);
    }

    /** @return array<int, string> */
    private static function resolve(string $path): array
    {
        $base = preg_replace('/\.(png|jpe?g)$/i', '', ltrim($path, '/'));
        [$width] = self::dimensions($path);

        $variants = [];
        foreach (array_unique([...self::WIDTHS, $width]) as $w) {
            if ($w && is_file(public_path("{$base}-{$w}.webp"))) {
                $variants[$w] = asset("{$base}-{$w}.webp");
            }
        }
        ksort($variants);

        return $variants;
    }

    public static function srcset(string $path): ?string
    {
        $variants = self::variants($path);

        return $variants
            ? implode(', ', array_map(fn ($url, $w) => "{$url} {$w}w", $variants, array_keys($variants)))
            : null;
    }

    /** The largest WebP variant, or the original file when none was generated. */
    public static function largest(string $path): string
    {
        $variants = self::variants($path);

        return $variants ? end($variants) : asset($path);
    }

    /** @return array{0: int|null, 1: int|null} */
    public static function dimensions(string $path): array
    {
        $size = @getimagesize(public_path(ltrim($path, '/')));

        return $size ? [$size[0], $size[1]] : [null, null];
    }
}
